template.solver:
def solve(m):
    c = m // 9
    best_max = -1
    best_min = -1
    for a in range(10):
        for b in range(10):
            if a == b:
                continue
            if (10 * a + b) % c != 0:
                continue
            # максимум
            digs = [d for d in range(9, -1, -1) if d != a and d != b]
            if digs[0] == 0:
                continue
            num = 0
            for d in digs:
                num = num * 10 + d
            num = num * 100 + 10 * a + b
            if num > best_max:
                best_max = num
            # минимум
            digs = [d for d in range(10) if d != a and d != b]
            if digs[0] == 0:
                digs = [digs[1], 0] + digs[2:]
            num = 0
            for d in digs:
                num = num * 10 + d
            num = num * 100 + 10 * a + b
            if best_min < 0 or num < best_min:
                best_min = num
    return best_max + best_min
